قَالَ /12 أَبُو عَبْدِ اللَّهِ /12 : كُنَّا عِنْدَ إِسْمَاعِيلَ ، فَذُكِرَ لَهُ حَدِيثُ /26 مُحَمَّدِ بْنِ إِسْحَاقَ L6811 /26 , عَنْ /26 عَمْرِو بْنِ شُعَيْبٍ L6144 /26 , عَنْ /26 أَبِيهِ L3815 /26 , عَنْ /93 جَدِّهِ L4980 /93 , /27 قُلْتُ : " يَا رَسُولَ اللَّهِ , /20 أَكْتُبُ عَنْكَ مَا أَسْمَعُ ؟ قَالَ : نَعَمْ " ، قُلْتُ : فِي الْغَضَبِ وَالرِّضَا ؟ /27 ، فَسَمِعْتُ إِسْمَاعِيلَ , يَقُولُ : أَعُوذُ بِاللَّهِ مِنَ الْكَذِبِ * 
@E4 @ 1 : 28 @   فقلت : كيف كان حال عمرو بن شعيب عند إسماعيل ، لم يكن يرضاه ؟ قال : قد روى عنه ، ولكن كان مذهب محمد بن سيرين , وأيوب ,   وابن عون ، ألا يكتبوا . قلت : سمع يحيى من عمر بن عامر شيئا ؟ قال : لا أعلم أنه حدث عنه بشيء . سألته من أكبر ، منصور بن المعتمر أو ابن زاذان ؟ قال : لا أدري . وذكر جرير بن حازم ، فقال : كان حافظا ، وقال مرة في بعض حديثه شيء . وقال أبو عبد الله ، سمعت إبراهيم بن سعد يحلف بالله ، أن ابن سمعان كذاب . وقال في إسحاق بن يحيى بن طلحة : ليس حديثه بشيء . وذكر حسين بن واقد ، فقال : ليس بذاك . وسئل عن علي بن غراب ، فقال ، كان حديثه ، حديث أهل الصدق . قلت له : سعيد بن عبد الجبار مكي ؟ قال : لا هذا من أهل الشام ، حدثنا أبو بدر عنه بحديثين ، وقد ضربت عليهما , قلت : وإيش حاله ؟ قال : حدث بأحاديث مناكير . سألته عن عسل بن سفيان ، فلين أمره . سألته عن بشر بن حرب ، فقال : نحن صيام وضعفه . سألته عن داود بن يزيد الأودي ، فقال هذا الزعافري وهو عم ابن إدريس ، سألوه عن حديث الشعبي لا يكون المهر أقل من عشرة ، فلم يعرفه ، فسأله شريك فلقنه ، فحدث به وضعفه . وسألته عن أزهر بن سنان ، فلينه ، وقال : حدث بحديث ذكره في الطلاق . 153 سألته عن عبد الله بن ميسرة , الذي حدث   عنه يزيد بن هارون , فلينه ، وقال : نحن نروي عنه . وسألته عن داود بن فراهيج ، فقال : هذا مديني ، ولين أمره . سألته عن أبي عامر الخزاز ، فقال : قد روى عنه ولين أمره .    @ 1 : 29 @   سألته عن عباد بن صهيب ، فقال : كان يرمي بالقدر ، وكان أمره قريبا من أبي عامر الخزاز . سألته عن الزبير بن سعيد ، فلين أمره . سألته عن عيسى بن المسيب ، فقال : هذا كوفي ولينه . سألته عن أبي داود نفيع ، وعن أبي الورقاء , فلين أمر نفيع , وضعف أبا الورقاء ، وقدم أبا داود عليه ، وقال : هو أمثل . سألته عن حارثة بن أبي الرجال ، فقال : ليس هو بذالك . وسألته عن أخيه عبد الرحمن , فقال : ليس به بأس . سألته عن ابن عجلان ، فقال : ثقة ، قلت : إن يحيى قد ضعفه ، قال : كان ثقة ، إنما اضطراب عليه حديث المقبري كان عن رجل ، جعل يصيره عن أبي هريرة . سألته عن رشدين ، قال : ليس أخبر أمره ، لا أدري . سألته قلت : شعبة , عن عتاب مولى ابن هرمز ، هو عتاب ابن من هو ؟ قال : لا أدري . قلت : الحكم بن عطية ، كيف هو ؟ قال : البصري ؟ قلت : نعم ، الذي روى عن ثابت ، قال : كان عندي   ليس به بأس ، ثم بلغني أنه حدث بأحاديث مناكير , وكأنه ضعفه . سألته عن عمران القطان ، فقال : ليس بذاك وضعفه . سألته عن إسماعيل بن رافع ، قال : لا أدري ، ابن أبي مليكة , عن عبد الرحمن بن السائب , فانتهر بيده ، وقال : حديث ذا ليس بشيء . وقال في حديث أبي النضر , عن أبي جعفر الرازي ، عن يزيد بن عبد الله ، قال : هذا شامي , فذكر حديث واثلة قصة البعير ، فقال : أبو جعفر ، لم يسمع من هذا ، إنما روى هذا عن محمد بن سعيد . والله وأعلم ، فترك محمد بن سعيد ، وقال : عن زيد . قلت : إيش حال محمد بن سعيد ؟ قال : يقولون , والله أعلم : إن أبا جعفر صلبه على الزندقة , وهو متروك الحديث . قلت : فأبو جابر البياضي , كيف هو ؟ قال : بلغني عن مالك , ,أنه كان يقول : كان يكذب .    @ 1 : 30 @   قلت : فكيف الحسن بن عمارة ؟ قال : متروك الحديث . سألته عن أبي هارون العبدي . قال : ليس هو بذاك . وسألته عن عباد بن كثير ، فقال : ليس هو بذاك ، قلت : كان فيه شيء من القدر ؟ قال : لا , إلا أن حديثه ليس بذاك . قلت له : ما تقول في سعيد بن جمهان ؟ فقال : ثقة ،   روى عنه : العوام بن حوشب ، وروى عنه : حماد , وأراه ذكر عبد الوارث وغيره . قلت : يروي عن يحيى القطان , ,أنه سئل عنه ، فلم يرضه , فقال : باطل ، وغضب ، وقال : ما قال هذا أحد غير علي بن المديني ، ما سمعت يحيى يتكلم فيه بشيء . وذكر عبد الله بن عثمان بن خثيم ، فقال : روى عن عطاء في الطلاق ناسيا أنه يلزمه ، وقد روى عن : ابن جريج , عن عطاء . خلافه . قلت : فكيف ابن خثيم ؟ قال : ابن جريج أثبت منه . حدثنا أبو عوانة ، حدثنا أبو بكر ، حدثنا أبو عبد الله أحمد بن محمد بن حنبل , قال : سمعت محمد بن جعفر الوركاني ، يقول : كنا عند هشيم ، فقال له رجل ، حدثنا سلمة الأحمر , عن حماد , عن إبراهيم , قال : كان أصحاب النبي صلى الله عليه وسلم يحرمون في المورد ، فقال هشيم : دعونا من حديث الكذابين ، فتبسم أبو عبد الله ، وقال : ليس من هذا شيء , وقال : قد رأيت سلمة . وسألت أبا عبد الله , عن أبي السمح ، قلت : كيف هو ؟ قال : قد روى عن أبي الهيثم ، أحاديث وتبسم ، قلت : كيف هو ؟ قال : ما أدري ما هو . قلت : فأبو الهيثم ؟   قال : ثقة . وقال : الحسن بن ذكوان ليس بذاك ، وقد روى عنه يحيى . وسألته عن سفيان بن حسين كيف هو ؟ قال : ليس بذاك ، وضعفه . وسألته عن إسحاق بن راشد ، فقال : ثقة . وقال في سور بن مصعب : ليس بشيء . قلت له : يحتج بحديث أبي الزبير ؟ فقال : أبو الزبير يروي عنه , ويحتج به . سألته عن مبارك بن فضالة ، قال : ما روى عن الحسن يحتج به ، وقال : دخل على أبي جعفر ، فجعل يقول : يا أمير المؤمنين , سمعت الحسن يقول ، وسمعت    @ 1 : 31 @   الحسن يقول ، ثم قال أبو عبد الله : كان أبو جعفر ، يعجبه أمر الحسن . سألته عن محمد بن جابر ، فقال : يروي عنه ، وقال : كان ابن مهدي يحدث عن محمد بن جابر ، ثم تركه بعد . 
